export function pointInRing(lat: number, lng: number, ring: [number, number][]): boolean {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const xi = ring[i][0], yi = ring[i][1];
    const xj = ring[j][0], yj = ring[j][1];
    const intersect = (yi > lng) !== (yj > lng) && lat < ((xj - xi) * (lng - yi)) / (yj - yi) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

export function findLouleParishForPoint(lat: number, lng: number): string | null {
  for (const [name, polys] of Object.entries(LOULE_PARISH_POLYGONS)) {
    for (const ring of polys) {
      if (pointInRing(lat, lng, ring)) return name;
    }
  }
  return null;
}
